// Con el descubrimiento completo pero sin solución confirmada, esta rama se
// tragaba cualquier mensaje: quien preguntaba el precio recibía otra vez el
// resumen y la misma pregunta. Estas intenciones tienen su propio manejador más
// abajo — el de precio incluso lee el catálogo real — y deben poder llegar.
const ATENDER_ANTES_DE_CONFIRMAR = new Set(["price", "proposal", "appointment", "objection_price_high", "handoff", "menu", "courtesy_close"]);
const ALLOWED_SOLUTIONS = new Set(['web_catalogo', 'chatbot_whatsapp_ia', 'pack_web_chatbot', 'asesor']);
const ALLOWED_ACTIONS = new Set(['none', 'handoff', 'proposal', 'appointment', 'media_fallback']);
const PROPOSAL_STATUSES = new Set(['none', 'requested', 'rendering', 'pending_approval', 'approved', 'rejected', 'sending', 'partially_sent', 'sent', 'failed', 'blocked_after_send_failure']);

function text(value) { return String(value == null ? '' : value).replace(/\s+/g, ' ').trim(); }
function bool(value) { return value === true || value === 1 || /^(true|1|yes|si)$/i.test(text(value)); }
function parseObject(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return { ...value };
  try { const parsed = JSON.parse(text(value) || '{}'); return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {}; } catch { return {}; }
}
function validEmail(value) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text(value)); }
function money(value) { return new Intl.NumberFormat('es-CO', { maximumFractionDigits: 0 }).format(Number(value || 0)); }

function safeContext(input) {
  const source = parseObject(input);
  const result = {
    schema_version: '3.0',
    conversation_id: text(source.conversation_id),
    first_name: text(source.first_name || source.name).split(/\s+/)[0] || '',
    business_type: text(source.business_type),
    project_goal: text(source.project_goal),
    pain_point: text(source.pain_point),
    current_process: text(source.current_process),
    impact: text(source.impact),
    desired_outcome: text(source.desired_outcome),
    discovery_urgency: text(source.discovery_urgency),
    discovery_depth: 0,
    discovery_done: false,
    last_question_code: text(source.last_question_code),
    last_question_hash: text(source.last_question_hash),
    recommended_solution: ALLOWED_SOLUTIONS.has(text(source.recommended_solution)) ? text(source.recommended_solution) : '',
    selected_solution: ALLOWED_SOLUTIONS.has(text(source.selected_solution)) ? text(source.selected_solution) : '',
    solution_confirmed: bool(source.solution_confirmed),
    price_requested: bool(source.price_requested),
    proposal_requested: bool(source.proposal_requested),
    proposal_delivery_status: PROPOSAL_STATUSES.has(text(source.proposal_delivery_status)) ? text(source.proposal_delivery_status) : 'none',
    proposal_sent: bool(source.proposal_sent) && text(source.proposal_delivery_status) === 'sent',
    proposal_accepted: bool(source.proposal_accepted) && bool(source.proposal_sent),
    objection_code: text(source.objection_code),
    human_required: bool(source.human_required),
    bot_muted: bool(source.bot_muted),
    opt_out: bool(source.opt_out),
    email: text(source.email),
    pipeline_stage: 'nuevo',
    next_action: '',
    conversation_summary: text(source.conversation_summary).slice(0, 420),
  };
  return recalculate(result);
}

function mergeInterpretation(context, interpretation) {
  const next = safeContext(context);
  const interpreted = parseObject(interpretation);
  const fields = parseObject(interpreted.extracted_fields);
  for (const key of ['business_type','project_goal','pain_point','current_process','impact','desired_outcome','discovery_urgency']) {
    const value = text(fields[key]);
    if (value) next[key] = value;
  }
  const extractedEmail = text(fields.email).toLowerCase();
  if (validEmail(extractedEmail)) next.email = extractedEmail;
  const selected = text(fields.selected_solution);
  if (ALLOWED_SOLUTIONS.has(selected)) next.selected_solution = selected;
  const intent = text(interpreted.intent);
  if (intent === 'confirm_chatbot') { next.selected_solution = 'chatbot_whatsapp_ia'; next.solution_confirmed = true; }
  if (intent === 'confirm_web') { next.selected_solution = 'web_catalogo'; next.solution_confirmed = true; }
  if (intent === 'select_pack') { next.selected_solution = 'pack_web_chatbot'; next.solution_confirmed = true; }
  if (intent === 'price') next.price_requested = true;
  if (intent === 'proposal') next.proposal_requested = true;
  return recalculate(next);
}

function recalculate(context) {
  const next = { ...context };
  const filled = [next.business_type, next.project_goal, next.pain_point, next.current_process, next.impact || next.discovery_urgency, next.desired_outcome].filter((value) => text(value));
  next.discovery_depth = filled.length;
  next.discovery_done = filled.length === 6;
  if (next.opt_out) { next.pipeline_stage = 'cerrado'; next.next_action = 'No contactar'; return next; }
  if (next.human_required || next.bot_muted) { next.pipeline_stage = 'handoff'; next.next_action = 'Esperar asesor'; return next; }
  if (!next.business_type && !next.project_goal) next.pipeline_stage = 'nuevo';
  else if (!next.discovery_done) next.pipeline_stage = 'descubrimiento';
  else if (next.proposal_requested) next.pipeline_stage = 'propuesta';
  else next.pipeline_stage = 'calificado';
  next.next_action = nextQuestion(next).action;
  return next;
}

function nextQuestion(context) {
  if (!text(context.business_type)) return { code: 'ask_business_type', action: 'Pedir rubro del negocio', question: '¿A qué se dedica tu negocio?' };
  if (!text(context.project_goal)) return { code: 'ask_project_goal', action: 'Pedir necesidad principal', question: '¿Qué quieres resolver primero?' };
  if (!text(context.pain_point)) return { code: 'ask_pain_point', action: 'Pedir dolor o problema actual', question: '¿Qué está pasando hoy que te llevó a buscarlo? Cuéntamelo con tus palabras.' };
  if (!text(context.current_process)) return { code: 'ask_current_process', action: 'Pedir situación actual', question: '¿Cómo lo están resolviendo hoy y en qué momento se complica más?' };
  if (!text(context.impact) && !text(context.discovery_urgency)) return { code: 'ask_impact', action: 'Pedir resultado deseado o urgencia', question: '¿Qué impacto tiene hoy en tu negocio o qué tan urgente es resolverlo?' };
  if (!text(context.desired_outcome)) return { code: 'ask_desired_outcome', action: 'Pedir resultado deseado o urgencia', question: 'Si esto funcionara bien, ¿qué tendría que cambiar primero para ti?' };
  if (!bool(context.solution_confirmed)) return { code: 'confirm_solution', action: 'Confirmar solución: chatbot, web, pack o asesor', question: '¿Prefieres priorizar chatbot, catálogo web o ambos?' };
  if (bool(context.proposal_requested) && !validEmail(context.email)) return { code: 'ask_email_for_proposal', action: 'Pedir correo y confirmar propuesta', question: '¿A qué correo quieres que enviemos la propuesta para revisión?' };
  if (bool(context.proposal_requested)) return { code: 'prepare_proposal', action: 'Preparar y enviar propuesta', question: '' };
  if (bool(context.price_requested)) return { code: 'show_catalog_prices', action: 'Mostrar precios del catálogo', question: '' };
  return { code: 'offer_next_step', action: 'Mostrar precios del catálogo', question: '¿Quieres revisar precios, preparar una propuesta o hablar con un asesor?' };
}

function sentenceFragment(value) {
  const normalized = text(value).replace(/\bwhatsapp\b/gi, 'WhatsApp');
  return normalized ? normalized.charAt(0).toLocaleLowerCase('es-CO') + normalized.slice(1) : '';
}

function buildSummary(context) {
  const parts = [];
  if (context.business_type) parts.push(`tienes ${context.business_type}`);
  if (context.project_goal) {
    // El objetivo se guarda con las palabras del cliente, y suele venir ya en
    // primera persona ("quiero que me contesten los pedidos"). Anteponerle
    // otro verbo produce "quieres mejorar quiero que...".
    const meta = sentenceFragment(context.project_goal);
    parts.push(
      /^(?:quiero|quisiera|queremos|necesito|necesitamos|busco|buscamos|me gustaria|me gustaría)\b/.test(meta)
        ? meta
        : `quieres mejorar ${meta}`,
    );
  }
  if (context.pain_point) parts.push(`el problema es ${sentenceFragment(context.pain_point)}`);
  if (context.current_process) parts.push(`hoy ${sentenceFragment(context.current_process)}`);
  if (context.impact && !text(context.pain_point).toLowerCase().includes(text(context.impact).toLowerCase())) parts.push(text(context.impact));
  if (context.desired_outcome) parts.push(sentenceFragment(context.desired_outcome));
  return parts.join('; ').slice(0, 420);
}

function renderCatalog(catalog) {
  const source = parseObject(catalog);
  const packages = parseObject(source.catalog_packages);
  const essential = packages['PKG-ESSENTIAL'] || packages.essential || {};
  const professional = packages['PKG-PROFESSIONAL'] || packages.professional || {};
  const ready = source.catalog_ready === true && Number(essential.price_project || 0) > 0 && Number(professional.price_project || 0) > 0;
  if (!ready) return { ok: false, reply: 'Ahora mismo no puedo confirmar precios con seguridad. Un asesor puede validarlos según el alcance.', reason_code: 'CATALOG_UNAVAILABLE' };
  return {
    ok: true,
    reply: `📦 Esencial: desde $${money(essential.price_project)}${Number(essential.price_monthly || 0) > 0 ? ` + $${money(essential.price_monthly)}/mes` : ''}\n🚀 Profesional: desde $${money(professional.price_project)}${Number(professional.price_monthly || 0) > 0 ? ` + $${money(professional.price_monthly)}/mes` : ''}\n🌐 Dominio: se cotiza aparte según disponibilidad.`,
    reason_code: 'CATALOG_PRICES_RENDERED',
  };
}

function renderIncludes(catalog) {
  const source = parseObject(catalog);
  const packages = parseObject(source.catalog_packages);
  const essential = packages['PKG-ESSENTIAL'] || packages.essential || {};
  const professional = packages['PKG-PROFESSIONAL'] || packages.professional || {};
  const lineas = [];
  if (text(essential.includes_text)) lineas.push(`📦 *${text(essential.name) || 'Esencial'}*: ${text(essential.includes_text)}`);
  if (text(professional.includes_text)) lineas.push(`🚀 *${text(professional.name) || 'Profesional'}*: ${text(professional.includes_text)}`);
  return lineas.join('\n\n');
}

function bogotaGreeting(now = new Date()) {
  let hour = 12;
  try {
    hour = Number(new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/Bogota',
      hour: '2-digit',
      hourCycle: 'h23',
    }).format(now));
  } catch {
    hour = now.getUTCHours() - 5;
    if (hour < 0) hour += 24;
  }
  if (hour >= 5 && hour < 12) return 'Buenos días';
  if (hour >= 12 && hour < 19) return 'Buenas tardes';
  return 'Buenas noches';
}

function renderProfessionalOpening(context) {
  const greeting = bogotaGreeting();
  const firstName = text(context && context.first_name);
  const salutation = firstName ? `${greeting}, ${firstName} 👋` : `${greeting} 👋`;
  return `${salutation} Soy *Luna de Luenio*.

Te ayudo con *web, chatbot y automatizaciones* para encontrar la opción adecuada para tu negocio, directamente por este chat.

Para orientarte bien, cuéntame brevemente: *¿a qué se dedica tu negocio?*`;
}

function safeReply(value) {
  const clean = String(value == null ? '' : value)
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
    .slice(0, 700);
  return clean.replace(/\$\s*(?:800\.000|500\.000|1\.200\.000|300\.000)/g, 'valor por confirmar');
}

function decideTurn(input) {
  const source = input && typeof input === 'object' ? input : {};
  const interpretation = parseObject(source.interpretation || source.interpretation_json);
  let context = mergeInterpretation(source.context || source.context_json, interpretation);
  const intent = text(interpretation.intent || source.intent);
  const kb = parseObject(source.approved_content || source.approved_content_json);
  let action = { type: 'none', payload: {} };
  let reason = 'DISCOVERY_NEXT_FIELD';
  let reply = '';

  if (intent === 'reset') {
    const preserveOptOut = context.opt_out;
    const preserveHuman = context.human_required;
    const preserveMute = context.bot_muted;
    context = safeContext({ conversation_id: context.conversation_id, first_name: context.first_name, opt_out: preserveOptOut, human_required: preserveHuman, bot_muted: preserveMute });
    reply = 'Listo, borré el contexto comercial de esta conversación. Empezamos de cero. ¿A qué se dedica tu negocio?';
    reason = 'RESET_APPLIED';
  } else if (intent === 'activate') {
    context.opt_out = false; context.human_required = false; context.bot_muted = false; context = recalculate(context);
    reply = context.proposal_sent
      ? 'Listo, vuelvo a atenderte. La propuesta anterior sigue registrada. ¿Quieres ajustarla o hablar con un asesor?'
      : context.proposal_requested
        ? 'Listo, vuelvo a atenderte. La solicitud de propuesta sigue pendiente de revisión. ¿Quieres continuar con ella o ajustar el alcance?'
        : `Listo, vuelvo a atenderte. ${nextQuestion(context).question}`;
    reason = 'BOT_REACTIVATED';
  } else if (intent === 'opt_out') {
    context.opt_out = true; context = recalculate(context);
    reply = 'Listo, no te escribiré más de forma automática. Si quieres retomar, escribe activar luna.';
    reason = 'OPT_OUT_APPLIED';
  } else if (intent === 'handoff') {
    context.human_required = true; context.bot_muted = true; context = recalculate(context);
    action = { type: 'handoff', payload: { reason: 'explicit_request' } };
    reply = 'Con gusto. Te paso con un asesor humano de Luenio en este chat. Para volver con el asistente, escribe activar luna.';
    reason = 'HANDOFF_REQUESTED';
  } else if (intent === 'media') {
    action = { type: 'media_fallback', payload: {} };
    reply = 'Puedo ayudarte mejor si me escribes qué necesitas resolver y a qué se dedica tu negocio.';
    reason = 'MEDIA_REQUIRES_PROCESSOR';
  } else if (context.opt_out) {
    action = { type: 'none', payload: {} };
    reply = '';
    reason = 'OPT_OUT_NO_REPLY';
  } else if (context.human_required || context.bot_muted) {
    action = { type: 'none', payload: {} };
    reply = '';
    reason = 'BOT_MUTED_NO_REPLY';
  } else if (
    intent === 'greeting' &&
    context.discovery_depth === 0 &&
    !context.business_type &&
    !context.project_goal
  ) {
    reply = renderProfessionalOpening(context);
    reason = 'OPENING_PROFESSIONAL';
  } else if (intent === 'includes') {
    // Con el alcance no se improvisa: si el catálogo no lo trae, pasa a un asesor.
    const detalle = renderIncludes(source.catalog || source.catalog_json);
    const pendienteInc = nextQuestion(context).question;
    const baseInc = detalle
      ? `${detalle}\n\n🌐 El dominio se cotiza aparte.`
      : 'El alcance exacto depende de lo que necesites. Un asesor te lo detalla sin compromiso, sin costo.';
    reply = pendienteInc ? `${baseInc}\n\n${pendienteInc}` : baseInc;
    reason = detalle ? 'CATALOG_INCLUDES_RENDERED' : 'INCLUDES_UNAVAILABLE';
  } else if (intent === 'about') {
    const pendienteAbout = nextQuestion(context).question;
    const quienSoy = 'Soy *Luna*, el asistente virtual de *Luenio* 🙂 No soy una persona, pero aquí mismo puedo mostrarte *precios*, ayudarte a ver qué opción te sirve, preparar una *propuesta* o pasarte con un *asesor humano*.';
    reply = pendienteAbout ? `${quienSoy}\n\n${pendienteAbout}` : quienSoy;
    reason = 'ABOUT_ASSISTANT';
  } else if (intent === 'courtesy_close') {
    reply = 'Con gusto 🙌 Quedo atenta por aquí. Si quieres, te muestro *precios*, preparo una *propuesta* o te paso con un *asesor*.';
    reason = 'COURTESY_CLOSE';
  } else if (interpretation.is_question === true && kb.found && kb.answer_template && !context.discovery_done) {
    // Una pregunta del cliente se responde y después se retoma el guion. Sin
    // esto la rama de descubrimiento se la traga y vuelve a preguntar lo mismo.
    const pendiente = nextQuestion(context).question;
    reply = pendiente ? `${kb.answer_template}

${pendiente}` : kb.answer_template;
    if (kb.requires_human) action = { type: 'handoff', payload: { reason: 'kb_requires_human' } };
    reason = kb.reason_code || 'KB_ANSWER_DURING_DISCOVERY';
  } else if (!context.discovery_done && !ATENDER_ANTES_DE_CONFIRMAR.has(intent)) {
    const next = nextQuestion(context);
    // Si el mensaje no aportó ningún dato es que no le entendimos. Repetir la
    // pregunta tal cual deja al cliente sin saber qué se espera de él.
    const aportes = Object.values(parseObject(interpretation.extracted_fields) || {}).filter((v) => text(v));
    const noEntendido = intent === 'general' && aportes.length === 0;
    reply = noEntendido
      ? `Perdón, no te seguí bien. Puedo mostrarte *precios*, preparar una *propuesta* o pasarte con un *asesor*.\n\n${next.question}`
      : next.question;
    reason = noEntendido ? 'DISCOVERY_REPHRASED' : `DISCOVERY_${next.code.toUpperCase()}`;
  } else if (!context.solution_confirmed && !ATENDER_ANTES_DE_CONFIRMAR.has(intent)) {
    context.recommended_solution = context.recommended_solution || (context.selected_solution || 'chatbot_whatsapp_ia');
    // La etapa que dejó escrita el turno anterior es la única memoria fiable de
    // si el resumen ya se presentó: el contexto en curso ya viene recalculado.
    const etapaPrevia = text(parseObject(source.context || source.context_json).pipeline_stage);
    const yaResumido = etapaPrevia === 'calificado' || etapaPrevia === 'propuesta';
    context.conversation_summary = buildSummary(context);
    reply = yaResumido
      ? nextQuestion(context).question
      : `Entiendo: ${context.conversation_summary}. ${nextQuestion(context).question}`;
    reason = yaResumido ? 'CONFIRM_SOLUTION_REASK' : 'DISCOVERY_COMPLETE_CONFIRM_SOLUTION';
  } else if (intent === 'confirm_chatbot' || context.selected_solution === 'chatbot_whatsapp_ia' && intent === 'price') {
    reply = intent === 'price'
      ? 'El chatbot no tiene un precio independiente fijo: depende del alcance, las integraciones y el volumen. ¿Quieres revisar el Pack del catálogo o prefieres hablar con un asesor?'
      : 'Perfecto, dejamos priorizado el chatbot para WhatsApp. El valor depende del alcance, las integraciones y el volumen. ¿Quieres revisar las opciones del catálogo o prefieres hablar con un asesor?';
    reason = 'CHATBOT_SCOPE_CONFIRMED';
  } else if (intent === 'confirm_web' || context.selected_solution === 'web_catalogo' && intent === 'price') {
    reply = 'Perfecto, dejamos priorizado el catálogo web. El valor depende del alcance y del volumen del catálogo. ¿Quieres revisar el Pack del catálogo o prefieres hablar con un asesor?';
    reason = 'WEB_SCOPE_CONFIRMED';
  } else if (intent === 'select_pack') {
    reply = 'Perfecto, dejamos priorizado el Pack web + chatbot. ¿Quieres que te muestre los precios del catálogo, que prepare una propuesta o prefieres un asesor?';
    reason = 'PACK_CONFIRMED';
  } else if (intent === 'proposal' || context.proposal_requested) {
    if (!context.solution_confirmed) {
      reply = 'Antes de preparar una propuesta, confirmemos si quieres chatbot, catálogo web o ambos.';
      reason = 'PROPOSAL_SOLUTION_REQUIRED';
    } else if (!validEmail(context.email)) {
      reply = 'Perfecto. ¿A qué correo quieres que enviemos la propuesta para revisión?';
      reason = 'PROPOSAL_ASK_EMAIL';
    } else {
      context.proposal_delivery_status = 'requested';
      action = { type: 'proposal', payload: { selected_solution: context.selected_solution } };
      reply = 'Perfecto. Prepararé un borrador para revisión de un asesor antes de enviarlo. Te confirmaré por este chat cuando esté aprobado.';
      reason = 'PROPOSAL_APPROVAL_REQUIRED';
    }
  } else if (intent === 'price') {
    const priced = renderCatalog(source.catalog || source.catalog_json);
    reply = `${priced.reply}${priced.ok ? '\n\n¿Quieres que te explique cuál encaja mejor, preparar una propuesta o hablar con un asesor?' : ''}`;
    reason = priced.reason_code;
  } else if (intent === 'appointment') {
    action = { type: 'appointment', payload: { timezone: 'America/Bogota' } };
    reply = validEmail(context.email) ? 'Puedo buscar tres horarios disponibles. Antes de reservar, necesitaré tu confirmación explícita del horario.' : 'Para coordinar una reunión necesito un correo válido. ¿Cuál quieres usar?';
    reason = 'APPOINTMENT_APPROVAL_REQUIRED';
  } else if (kb.found && kb.answer_template) {
    reply = kb.answer_template;
    if (kb.requires_human) action = { type: 'handoff', payload: { reason: 'kb_requires_human' } };
    reason = kb.reason_code || 'KB_APPROVED_ANSWER';
  } else {
    // Repetir la pregunta tal cual es lo que más pierde a un cliente: si no le
    // entendimos, primero se le dice qué puede pedir.
    const pendiente = nextQuestion(context).question;
    const orientacion = 'No estoy segura de haber entendido. Puedo mostrarte *precios*, preparar una *propuesta* o pasarte con un *asesor*.';
    reply = pendiente ? `${orientacion}

${pendiente}` : orientacion;
    reason = 'FALLBACK_ORIENTATION';
  }

  context = recalculate(context);
  context.conversation_summary = buildSummary(context);
  if (!ALLOWED_ACTIONS.has(action.type)) action = { type: 'none', payload: {} };
  const terminalSilence = intent === 'handoff' || intent === 'opt_out' || context.opt_out || context.human_required || context.bot_muted;
  const nextQuestionCode = terminalSilence ? '' : nextQuestion(context).code;
  return { reply: safeReply(reply), next_question_code: nextQuestionCode, crm_updates: context, action_request: action, reason_code: reason };
}

const input = $input.first()?.json || {};
const result = decideTurn(input);
return [{ json: { ...result, source_hash: String(input.source_hash || ''), environment: String(input.environment || 'staging') } }];
